const express = require('express');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();

prisma.$use(async (params, next) => {
  if (params.model === 'ClientContract') {
    // Secure merge: enforce tenantId strictly and prevent client override
    params.args.where = {
      ...params.args.where,
      tenantId: params.args.userTenantId
    };
  }
  return next(params);
});

app.get('/api/contracts', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Strip tenantId from untrusted client query parameters
  const { tenantId: _, ...safeFilters } = req.query;

  const contracts = await prisma.clientContract.findMany({
    userTenantId: req.user.tenantId,
    where: {
      ...safeFilters,
      tenantId: req.user.tenantId
    }
  });

  res.json({ contracts });
});

app.listen(3037);
